import React from 'react';
import { MultiSelect } from 'carbon-components-react';

const items = [
  { id: 'item-1', text: 'Option 1' },
  { id: 'item-2', text: 'Option 2' },
  { id: 'item-3', text: 'An example option that is really long to show what should be done to handle long text' },
  { id: 'item-4', text: 'Option 3' },
  { id: 'item-5', text: 'Option 4' },
];

const App = () => {
  return (
    <MultiSelect
      label="MultiSelect Label"
      items={items}
      itemToString={(item) => (item ? item.text : '')}
      initialSelectedItems={[items[0], items[1]]}
    />
  );
};

export default App;
